--- /dev/null
+++ b/repro/input.ts
@@ -0,0 +1,31 @@
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">
+})
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>> 
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> } 
+    : T['_type']
+
+type Test = Unwrap<typeof value>
+
+// Control from the report: assertion on a separate line.
+const strWrapper = stringWrapper() as Wrapper<"hello">;
+const value2 = objWrapper({
+    prop1: strWrapper
+});
+type Test2 = Unwrap<typeof value2>
+
+// Shows the computed type is right (display-only).
+type Test3 = Unwrap<typeof value>["prop1"]
diff --git a/repro/repro.js b/repro/repro.js
new file mode 100644
index 000000000..98e188a46
--- /dev/null
+++ b/repro/repro.js
@@ -0,0 +1,30 @@
+// Usage: node repro/repro.js [path/to/typescript]   (default: this checkout's built/local/typescript.js)
+const path = require("path");
+const ts = require(process.argv[2] || path.join(__dirname, "../built/local/typescript.js"));
+const file = path.join(__dirname, "input.ts");
+const program = ts.createProgram([file], { strict: true, noEmit: true });
+const checker = program.getTypeChecker();
+const sf = program.getSourceFile(file);
+const ls = ts.createLanguageService({
+    getScriptFileNames: () => [file], getScriptVersion: () => "1",
+    getScriptSnapshot: f => ts.sys.fileExists(f) ? ts.ScriptSnapshot.fromString(ts.sys.readFile(f)) : undefined,
+    getCurrentDirectory: () => __dirname, getCompilationSettings: () => ({ strict: true }),
+    getDefaultLibFileName: o => ts.getDefaultLibFilePath(o), fileExists: ts.sys.fileExists, readFile: ts.sys.readFile,
+});
+console.log("TypeScript", ts.version);
+const results = {};
+for (const name of ["Test", "Test2", "Test3"]) {
+    const decl = sf.statements.find(s => ts.isTypeAliasDeclaration(s) && s.name.text === name);
+    const t = checker.getTypeAtLocation(decl.name);
+    const printed = checker.typeToString(t, decl, ts.TypeFormatFlags.InTypeAlias | ts.TypeFormatFlags.NoTruncation);
+    const qi = ls.getQuickInfoAtPosition(file, decl.name.getStart());
+    results[name] = printed;
+    console.log(`${name.padEnd(5)} typeToString: ${printed}`);
+    console.log(`${"".padEnd(5)} quickinfo:    ${ts.displayPartsToString(qi.displayParts).replace(/\s+/g, " ")}`);
+}
+const expected = '{ prop1: "hello"; }';
+if (results.Test !== expected) {
+    console.log(`\nBUG: Test printed as ${results.Test}, expected ${expected}`);
+    process.exit(1);
+}
+console.log("\nOK");
